exercise.solution:
try:
    with open("datos.txt") as f:
        contenido = int(f.read().strip())
    print(f"El número es {contenido}")
except FileNotFoundError:
    print("El archivo no existe.")
except ValueError:
    print("El contenido no es un número válido.")
finally:
    print("Fin del intento.")
